mapper.select:
    select id,plan_name,cycle,team_id,team_name,begin_date,end_date,`status`,
			 remark,dormancy_begin,dormancy_end,factory_id,factory_name,update_time,
             update_person,update_person_no
      from (SELECT a.id,max(a.plan_name) plan_name,max(a.cycle) cycle,max(a.team_id) team_id,
						 max(a.team_name) team_name,max(a.begin_date) begin_date,max(a.end_date) end_date,max(a.`status`) `status`,
						 max(a.remark) remark,max(a.dormancy_begin) dormancy_begin,max(a.dormancy_end) dormancy_end,
						 GROUP_CONCAT(b.factory_id) factory_id,GROUP_CONCAT(c.field_name) as factory_name,max(a.update_time) update_time
						 ,max(a.update_person) update_person,max(a.update_person_no) update_person_no
			 FROM safety_spot_check_plan A
			 LEFT JOIN safety_spot_link_plan_factory B ON A.ID = B.PLAN_ID
			 LEFT JOIN safety_field_manage c on b.factory_id = c.id
			where 1 = 1

      and a.status = #{param.status}


      and a.plan_name like concat('%',#{param.planName},'%')


      and a.teamId = #{param.teamId}


      and a.team_name like concat('%',#{param.teamName},'%')


      and a.end_date >= #{param.beginDate}



        and a.begin_date <= #{param.endDate}



      and b.factory_id in

        #{item}




         and a.begin_date <= #{param.beginDate} and a.end_date > #{param.endDate} 


			group by a.id) tmp
    where 1 = 1

      and FIND_IN_SET(#{param.factoryId},factory_id)

    ORDER BY update_time desc


        limit ${param.offset}, ${param.limit}


        limit ${param.limit}

select count(1) from (SELECT a.id,max(a.plan_name) plan_name,max(a.cycle) cycle,max(a.team_id) team_id, max(a.team_name) team_name,max(a.begin_date) begin_date,max(a.end_date) end_date,max(a.`status`) `status`, max(a.remark) remark,max(a.dormancy_begin) dormancy_begin,max(a.dormancy_end) dormancy_end, GROUP_CONCAT(b.factory_id) factory_id,GROUP_CONCAT(c.field_name) as factory_name,max(a.update_time) update_time ,max(a.update_person) update_person,max(a.update_person_no) update_person_no FROM safety_spot_check_plan A LEFT JOIN safety_spot_link_plan_factory B ON A.ID = B.PLAN_ID LEFT JOIN safety_field_manage c on b.factory_id = c.id where 1 = 1
and a.status = #{param.status}
and a.plan_name like concat('%',#{param.planName},'%')
and a.teamId = #{param.teamId}
and a.team_name like concat('%',#{param.teamName},'%')
and a.end_date >= #{param.beginDate}
and a.begin_date <= #{param.endDate}
and b.factory_id in
#{item}
group by a.id) tmp where 1 = 1
and FIND_IN_SET(#{param.factoryId},factory_id)
